import { useResource } from '../../hooks/useResource';
import React, { useEffect, useRef, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { Camera, Mail, Phone, User, Calendar, Link2, ShieldCheck } from 'lucide-react';
import { toast } from 'sonner';
import SummaryApi from '../../common';
import { setUserDetails } from '../../store/userSlice';
import TriangleMazeLoader from '../TriangleMazeLoader';
import WorkspacePanel from '../WorkspacePanel';
import GlassButton from '../GlassButton';
import StorageService from '../../utils/storageService';
import CookieManager from '../../utils/cookieManager';
import uploadImage from '../../helpers/uploadImage';
import { useOnlineStatus } from '../../App';

/**
 * Settings → Profile. This was the whole of pages/Profile.js; the page frame
 * (DashboardLayout + heading) now belongs to SettingsPage, and /profile
 * redirects there. Behaviour is unchanged — same fetch, same save, same
 * upload-link switch.
 */

const getFormData = (user) => ({
  name: user?.name || '',
  email: user?.email || '',
  phone: user?.phone || '',
  age: user?.age || '',
  profilePic: user?.profilePic || '',
});

const ProfileSettingsSection = () => {
  const dispatch = useDispatch();
  const { isOnline } = useOnlineStatus();
  const user = useSelector((state) => state?.user?.user);
  const [formData, setFormData] = useState(() => getFormData(user));
  const [initialFormData, setInitialFormData] = useState(() => getFormData(user));
  const [selectedImage, setSelectedImage] = useState(null);
  const pictureInput = useRef(null);
  const draftDirty = useRef(false);
  const [saving, setSaving] = useState(false);
  const [allowLoginFreeUploadLinks, setAllowLoginFreeUploadLinks] = useState(Boolean(user?.allowLoginFreeUploadLinks));
  const [uploadLinkPreferenceSaving, setUploadLinkPreferenceSaving] = useState(false);

  const { loading, error } = useResource(isOnline ? SummaryApi.current_user.url : null, next => {
    dispatch(setUserDetails(next)); StorageService.setUserDetails(next);
    if (!draftDirty.current) { setFormData(getFormData(next)); setInitialFormData(getFormData(next)); }
  });
  useEffect(() => { if (error) toast.error(error); }, [error]);

  useEffect(() => {
    setAllowLoginFreeUploadLinks(Boolean(user?.allowLoginFreeUploadLinks));
  }, [user?.allowLoginFreeUploadLinks]);

  const handleUploadLinkPreference = async () => {
    if (uploadLinkPreferenceSaving || !isOnline) return;
    const nextValue = !allowLoginFreeUploadLinks;
    setUploadLinkPreferenceSaving(true);
    try {
      const response = await fetch(SummaryApi.myUploadLinkPreference.url, {
        method: SummaryApi.myUploadLinkPreference.method,
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ allowLoginFreeUploadLinks: nextValue }),
      });
      const result = await response.json();
      if (!result.success) throw new Error(result.message || 'Could not update secure upload-link access');
      const updatedUser = { ...user, allowLoginFreeUploadLinks: result.data.allowLoginFreeUploadLinks };
      setAllowLoginFreeUploadLinks(result.data.allowLoginFreeUploadLinks);
      dispatch(setUserDetails(updatedUser));
      StorageService.setUserDetails(updatedUser);
      toast.success(result.data.allowLoginFreeUploadLinks ? 'Login-free upload links enabled' : 'Login-free upload links disabled');
    } catch (error) {
      toast.error(error.message || 'Could not update secure upload-link access');
    } finally {
      setUploadLinkPreferenceSaving(false);
    }
  };

  const isDirty = Boolean(selectedImage) || Object.keys(initialFormData).some((key) => formData[key] !== initialFormData[key]);
  draftDirty.current = isDirty;

  const handleChange = (event) => {
    const { name, value } = event.target;
    const nextValue = name === 'phone' || name === 'age' ? value.replace(/\D/g, '') : value;
    setFormData((current) => ({ ...current, [name]: nextValue }));
  };

  const handleImageChange = (event) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setSelectedImage(file);
    setFormData((current) => ({ ...current, profilePic: URL.createObjectURL(file) }));
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    if (!isDirty || saving) return;
    if (!isOnline) {
      toast.error('You are offline. Please check your internet connection.');
      return;
    }

    setSaving(true);
    try {
      let profilePic = formData.profilePic;
      if (selectedImage) {
        const imageData = await uploadImage(selectedImage);
        profilePic = imageData.url;
      }

      const response = await fetch(SummaryApi.updateProfile.url, {
        method: SummaryApi.updateProfile.method,
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: formData.name.trim(),
          phone: formData.phone.trim(),
          age: formData.age,
          profilePic,
        }),
      });
      const data = await response.json();
      if (!data.success) throw new Error(data.message || 'Failed to update profile');

      CookieManager.setUserDetails({
        _id: data.data._id,
        name: data.data.name,
        email: data.data.email,
        role: data.data.role,
      });
      StorageService.setUserDetails(data.data);
      dispatch(setUserDetails(data.data));
      setSelectedImage(null);
      setFormData(getFormData(data.data));
      setInitialFormData(getFormData(data.data));
      toast.success('Profile saved successfully');
    } catch (error) {
      console.error('Error updating profile:', error);
      toast.error(error.message || 'Failed to update profile');
    } finally {
      setSaving(false);
    }
  };

  return (
    <>
      {(loading || saving) && <div className="modal-backdrop fixed inset-0 z-50 flex items-center justify-center"><TriangleMazeLoader /></div>}

      <WorkspacePanel as="section" id="profile" aria-label="Profile settings" title="Profile" icon={User} actions={
        <GlassButton type="submit" form="profile-settings-form" variant="primary" disabled={!isDirty || saving}>{saving ? 'Saving...' : 'Save changes'}</GlassButton>
      }>
      <form id="profile-settings-form" onSubmit={handleSubmit} className="relative">
        <div className="border-b border-[var(--divider)] p-5 sm:p-6">
          <div className="relative flex items-center gap-4">
            <div className="flex h-20 w-20 items-center justify-center overflow-hidden rounded-full border border-[var(--glass-border-strong)] bg-[var(--glass-bg)] text-2xl font-bold text-[var(--text-primary)] backdrop-blur-md">
              {formData.profilePic ? <img src={formData.profilePic} alt={formData.name || 'Profile'} className="h-full w-full object-cover" /> : (formData.name || 'U').trim().charAt(0).toUpperCase()}
            </div>
            <div>
              <button type="button" aria-controls="profile-picture" onClick={() => pictureInput.current?.click()} className="inline-flex cursor-pointer items-center gap-2 rounded text-left text-base font-semibold text-[var(--eyebrow-fg)] hover:opacity-80 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-accent-text"><Camera size={16} /> Change profile picture</button>
              <input ref={pictureInput} id="profile-picture" type="file" accept="image/*" onChange={handleImageChange} className="hidden" />
              <p className="mt-1 text-sm text-[var(--text-secondary)]">JPG, PNG or WEBP</p>
            </div>
          </div>
        </div>

        <div className="border-b border-[var(--divider)] p-5 sm:p-6">
          <div className="relative flex flex-col gap-5 sm:flex-row sm:items-center sm:justify-between">
            <div className="flex items-start gap-3">
              <div className="mt-0.5 rounded-xl border border-[var(--glass-border)] bg-[var(--glass-bg)] p-2 text-[var(--text-primary)]"><Link2 size={19} /></div>
              <div>
                <div className="flex items-center gap-2"><h3 className="text-base font-bold text-[var(--text-primary)]">Login-free secure upload links</h3><ShieldCheck size={16} className="text-accent-text" /></div>
                <p className="mt-1 max-w-xl text-sm text-[var(--text-secondary)]">When enabled, an admin-generated link can open only its selected project's or service's upload form without your portal login. Turn it off to require credential verification.</p>
              </div>
            </div>
            <button
              type="button"
              role="switch"
              aria-label="Allow login-free secure upload links"
              aria-checked={allowLoginFreeUploadLinks}
              aria-busy={uploadLinkPreferenceSaving}
              onClick={handleUploadLinkPreference}
              disabled={uploadLinkPreferenceSaving || !isOnline}
              className={`relative h-8 w-14 shrink-0 rounded-full border-[length:var(--glass-border-width)] transition-colors duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent-text focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-60 ${
                allowLoginFreeUploadLinks
                  ? 'border-accent-600 bg-accent-500'
                  : 'border-[var(--glass-border-strong)] bg-[var(--text-muted)]'
              }`}
            >
              <span
                aria-hidden="true"
                className={`absolute left-0 top-1 h-6 w-6 rounded-full bg-white shadow-md ring-1 ring-black/10 transition-transform duration-200 ${
                  allowLoginFreeUploadLinks ? 'translate-x-7' : 'translate-x-1'
                }`}
              />
            </button>
          </div>
        </div>

        <div className="p-5 sm:p-6">
          <div className="relative grid gap-6 sm:grid-cols-2">
            <label className="block"><span className="mb-2 flex items-center gap-2 text-base font-semibold text-[var(--text-primary)]"><User size={16} className="text-[var(--text-muted)]" /> Full name</span><input name="name" value={formData.name} onChange={handleChange} required className="w-full border-0 border-b border-[var(--glass-border-strong)] bg-transparent px-0 py-2 text-base text-[var(--text-primary)] outline-none transition focus:border-accent-text focus:ring-0" /></label>
            <label className="block"><span className="mb-2 flex items-center gap-2 text-base font-semibold text-[var(--text-primary)]"><Mail size={16} className="text-[var(--text-muted)]" /> Email address</span><input name="email" value={formData.email} readOnly className="w-full border-0 border-b border-[var(--glass-border)] bg-transparent px-0 py-2 text-base text-[var(--text-primary)] outline-none" /></label>
            <label className="block"><span className="mb-2 flex items-center gap-2 text-base font-semibold text-[var(--text-primary)]"><Phone size={16} className="text-[var(--text-muted)]" /> Phone number</span><input name="phone" type="tel" inputMode="numeric" pattern="[0-9]*" value={formData.phone} onChange={handleChange} className="w-full border-0 border-b border-[var(--glass-border-strong)] bg-transparent px-0 py-2 text-base text-[var(--text-primary)] outline-none transition focus:border-accent-text focus:ring-0" /></label>
            <label className="block"><span className="mb-2 flex items-center gap-2 text-base font-semibold text-[var(--text-primary)]"><Calendar size={16} className="text-[var(--text-muted)]" /> Age</span><input name="age" type="text" inputMode="numeric" pattern="[0-9]*" maxLength="3" value={formData.age} onChange={handleChange} className="w-full border-0 border-b border-[var(--glass-border-strong)] bg-transparent px-0 py-2 text-base text-[var(--text-primary)] outline-none transition focus:border-accent-text focus:ring-0" /></label>
          </div>
        </div>
      </form>
      </WorkspacePanel>
    </>
  );
};

export default ProfileSettingsSection;
